def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    # Use the most frequent non-separator color as the background.
    cells = [
        grid[r][c]
        for r in range(h) if r not in sep_rows
        for c in range(w) if c not in sep_cols
    ]
    bg = max(set(cells), key=cells.count)

    def segments(length, separators):
        cuts = [-1] + separators + [length]
        return [(cuts[i] + 1, cuts[i + 1]) for i in range(len(cuts) - 1)
                if cuts[i + 1] > cuts[i] + 1]

    row_groups = segments(h, sep_rows)
    col_groups = segments(w, sep_cols)

    out = []
    for r0, r1 in row_groups:
        row = []
        for c0, c1 in col_groups:
            count = sum(
                grid[r][c] != bg
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            row.append(1 if count >= 2 else bg)
        out.append(row)
    return out
